  {
    "path": ".github/workflows/android.yml",
    "label": "android.yml",
    "language": "yaml",
    "descriptionZh": "GitHub Actions 自动签名构建与 Release 发布工作流。",
    "descriptionEn": "GitHub Actions CI workflow for signed APK release.",
    "content": "name: Build & Release APK\n\non:\n  push:\n    branches: [ \"main\" ]\n    tags: [ \"v*\" ]\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\njobs:\n  release-apk:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Checkout repository\n        uses: actions/checkout@v5\n\n      - name: Set up JDK 17\n        uses: actions/setup-java@v5\n        with:\n          distribution: 'temurin'\n          java-version: '17'\n\n      - name: Accept Android SDK Licenses\n        run: yes | \"$ANDROID_HOME/cmdline-tools/latest/bin/sdkmanager\" --licenses > /dev/null || true\n\n      - name: Setup Gradle 8.9\n        uses: gradle/actions/setup-gradle@v6\n        with:\n          gradle-version: '8.9'\n\n      - name: Write Persistent Signing Keystore\n        working-directory: android-module/app\n        run: |\n          echo \"\" | base64 -d > signing.p12\n\n      - name: Build Signed Single-DEX Release APK\n        working-directory: android-module\n        run: |\n          gradle assembleRelease --no-daemon --stacktrace\n          cp app/build/outputs/apk/release/app-release.apk ../Gemini-Eye.apk\n\n      - name: Publish to GitHub Releases\n        uses: softprops/action-gh-release@v2\n        with:\n          tag_name: v2.0.${{ github.run_number }}\n          name: Gemini-Eye v2.0.${{ github.run_number }}\n          body: \"**v2.0.0 Purely In-App Cronet/gRPC ProtoBuf & ViewModel Interception (Zero Web Fallback)**: Removed all WebView / `gemini.google.com/usage` HTTP polling and `INTERNET` permission; implemented non-destructive Cronet (`org.chromium.net.UrlRequest` / `BidirectionalStream`) & gRPC (`io.grpc.ClientInterceptor` / `Channel` / `ClientCall.Listener`) raw `ByteArray`/`ByteBuffer` stream interception with a binary ProtoBuf wire-format scanner (`5h` & `Weekly` reset epochs + percentage/usage fields); added `Throwable`-guarded `ViewModel` / `StateFlow` / `LiveData` / `Repository` memory hooks; preserved single-line capsule HUD (`MIUIX` / `MD3`, `EN` / `CN`) and `ModernQuotaModule` (API 102) Single-HUD Exclusion.\"\n          files: Gemini-Eye.apk\n"
  }
